const body = $input.first().json.body || $json;
const job = body.job || body;
const client = body.client || {};

const results = [];

const title = job.title || '';
const link = job.url || job.link || job.job_url || '';
const content = job.description || '';
const pubDate = job.postedAt || new Date().toISOString();
const scoreRedFlags = job.scoreRedFlags || null;
const effortEstimateHours = job.effortEstimateHours || null;
const reasoning = job.reasoning || '';

const clientInfo = {
  location: client.location || '',
  paymentVerified: client.paymentVerified || false,
  totalSpent: client.totalSpent || 0,
  hireRate: client.hireRate || 0,
  rating: client.rating || 0,
  rankLabel: client.rankLabel || ''
};

if (!title) return []; // skip malformed payloads

results.push({
  json: {
    title,
    link,
    content,
    pubDate,
    scoreRedFlags,
    effortEstimateHours,
    reasoning,
    client: clientInfo
  }
});

return results;

const originalItems = $('Parse Webhook Payload').all();

const results = [];

for (let i = 0; i < items.length; i++) {
  const aiItem = items[i];
  const originalItem = originalItems[i];

  if (!originalItem) continue;

  let parsed;
  try {
    let rawText = aiItem.json.output[0].content[0].text;
    // Strip markdown code fences like ```json ... ```
    rawText = rawText.replace(/```json\s*/i, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(rawText);
  } catch (e) {
    continue;
  }

  if (parsed.relevant === true) {
    results.push({
      json: {
        title: originalItem.json.title,
        link: originalItem.json.link,
        pubDate: originalItem.json.pubDate,
        reason: parsed.reason
      }
    });
  }
}

return results;

