const body = $json.body;

// Slack's one-time URL verification handshake (JSON body, Events API only)
if (body.type === 'url_verification') {
  return [{
    json: {
      is_challenge: true,
      challenge: body.challenge
    }
  }];
}

// Button clicks (block_actions) come as form-urlencoded with a JSON string in `payload`
if (body.payload) {
  let parsedPayload;
  try {
    parsedPayload = JSON.parse(body.payload);
  } catch (e) {
    parsedPayload = null;
  }

  return [{
    json: {
      is_challenge: false,
      payload: parsedPayload
    }
  }];
}

// Fallback for anything else (e.g. Events API notifications)
return [{
  json: {
    is_challenge: false,
    event: body.event || {}
  }
}];

const payload = $json.payload;

if (!payload || !payload.actions || !payload.actions[0]) {
  return [{ json: { valid: false } }];
}

const action = payload.actions[0];

return [{
  json: {
    valid: true,
    action_id: action.action_id,
    value: action.value,
    response_url: payload.response_url,
    user: payload.user ? payload.user.username : 'someone'
  }
}];
